b.mc("Nombres propios", 1, 2, "¿Cuál de estas palabras es un nombre propio?", "Teide", ["volcán", "montaña", "isla"], "Tiene mayúscula.", "Teide es el nombre de un volcán concreto.")
b.mc("Sinónimos y antónimos", 1, 2, "¿Cuál es lo contrario de «día»?", "noche", ["mañana", "tarde", "hoy"], "Cuando hay oscuridad.", "día ↔ noche.")
b.mc("Ortografía", 2, 2, "¿Cómo se escribe lo que ponen las gallinas?", "huevo", ["uevo", "buevo", "huebo"], "Empieza con h y lleva v.", "Se escribe «huevo».")
b.mc("Verbos", 2, 2, "Completa: «Ayer ___ al parque.»", "fui", ["voy", "iré", "ir"], "Ayer = pasado.", "Ayer fui al parque.")
b.mc("Acentuación", 3, 2, "¿Cuál es la sílaba que suena más fuerte en «ventana»?", "ta", ["ven", "na", "Ninguna"], "ven-TA-na.", "La sílaba tónica es «ta».")
b.tf("Mayúsculas", 1, 2, "Después de un punto se escribe con mayúscula.", True, "Empieza una frase nueva.", "Tras el punto, mayúscula.")


# ---- Más parejas (también las usa «Memoria Eureka») ----
b.match("Clases de palabras", 1, 3, "Une cada palabra con su clase.", [["gato", "sustantivo"], ["rojo", "adjetivo"], ["correr", "verbo"], ["ayer", "adverbio"]], "Piensa qué hace cada palabra en la frase.", "gato: nombre · rojo: cómo es · correr: acción · ayer: cuándo.")
b.match("Sinónimos y antónimos", 1, 4, "Une cada palabra con su contrario.", [["alto", "bajo"], ["ganar", "perder"], ["abrir", "cerrar"], ["día", "noche"]], "Busca el antónimo.", "Son pares de antónimos.")
b.match("Formación de palabras", 2, 4, "Une cada palabra con su familia.", [["pan", "panadero"], ["zapato", "zapatería"], ["libro", "librería"], ["flor", "florero"]], "Misma raíz.", "Cada derivada comparte la raíz de la palabra primitiva.")
b.match("Géneros literarios", 1, 5, "Une cada texto con su género.", [["Un poema", "lírico"], ["Una obra de teatro", "dramático"], ["Una novela", "narrativo"], ["Una noticia", "periodístico"]], "Piensa en cómo se presenta cada texto.", "Cada texto pertenece a un género distinto.")


